mapper.select:
select version_id, biz_key, content_hash, payload, first_sync_time, last_sync_time, hit_count
from ${tableName}
where biz_key = #{bizKey}
order by last_sync_time desc, version_id desc
limit 1

select version_id, biz_key, content_hash, payload, first_sync_time, last_sync_time, hit_count
from ${tableName}
where version_id = #{versionId}

select version_id, biz_key, content_hash, first_sync_time, last_sync_time, hit_count
from ${tableName}

    and biz_key = #{bizKey}

order by version_id desc

select sync_id, resource_key, biz_key, http_status, result, version_id, raw_bytes, cost_ms, message,
       trigger_type, sync_time
from option_resource_sync

    and resource_key = #{resourceKey}
    and biz_key = #{bizKey}
    and result = #{result}

order by sync_id desc
